#include <iostream>
#include <queue>
#include <functional>
#include <string>
using namespace std;

class WorkerPool {
    queue<function<void()>> tasks;
public:
    void addTask(function<void()> task) { tasks.push(task); }

    void run(int numWorkers) {
        int worker = 1;
        while (!tasks.empty()) {
            cout << "Worker " << worker << ": ";
            tasks.front()();
            tasks.pop();
            worker = (worker % numWorkers) + 1;
        }
    }
};

int main() {
    WorkerPool pool;
    pool.addTask([]() { cout << "Task 1: Process data" << endl; });
    pool.addTask([]() { cout << "Task 2: Send email" << endl; });
    pool.addTask([]() { cout << "Task 3: Generate report" << endl; });
    pool.addTask([]() { cout << "Task 4: Backup files" << endl; });
    pool.addTask([]() { cout << "Task 5: Clean cache" << endl; });
    pool.run(3);
    return 0;
}
